  <body>
    <a class="skip-link" href="#main">Skip to main content</a>
    <div id="app"></div>

    <script>
      const state = {
        submitted: false,
        values: {
          fullName: "",
          email: "",
          phone: "",
        },
      };

      const app = document.getElementById("app");

      function SupportCopy() {
        return `
          <aside class="card sidebar" aria-labelledby="support-hours-title">
            <h2 id="support-hours-title">What happens next</h2>
            <p>Send a message and our support team will review it during business hours.</p>
            <ul>
              <li>Required fields help us respond faster.</li>
              <li>Phone is optional, but useful for urgent follow-up.</li>
            </ul>
          </aside>
        `;
      }

      function fieldError(id, message, show) {
        return `<p class="field-error" id="${id}" ${show ? "" : "hidden"}>${message}</p>`;
      }

      function FormField({ id, label, name, type = "text", value, required = false, hint = "", error = "", autocomplete = "", inputmode = "" }) {
        const errorId = `${id}-error`;
        const hintId = hint ? `${id}-hint` : "";
        const describedBy = [hintId, errorId].filter(Boolean).join(" ");
        const isInvalid = state.submitted && Boolean(error);

        return `
          <div class="form-field">
            <label for="${id}">${label}${required ? ' <span class="required" aria-hidden="true">*</span>' : ""}</label>
            <input
              id="${id}"
              name="${name}"
              type="${type}"
              value="${escapeHtml(value)}"
              ${required ? "required" : ""}
              ${autocomplete ? `autocomplete="${autocomplete}"` : ""}
              ${inputmode ? `inputmode="${inputmode}"` : ""}
              aria-describedby="${describedBy}"
              ${isInvalid ? 'aria-invalid="true"' : ""}
            />
            ${hint ? `<p class="field-hint" id="${hintId}">${hint}</p>` : ""}
            ${fieldError(errorId, error, isInvalid)}
          </div>
        `;
      }

      function ContactForm() {
        const errors = validate(state.values);

        return `
          <section class="card form-card" aria-labelledby="contact-form-title">
            <h2 id="contact-form-title">Contact support</h2>
            <p class="status ${state.submitted && Object.keys(errors).length ? "error" : "success"}" aria-live="polite" aria-atomic="true">
              ${state.submitted && Object.keys(errors).length ? "Please correct the highlighted fields before sending." : ""}
            </p>
            <form id="contact-form" novalidate>
              ${FormField({
                id: "full-name",
                label: "Full name",
                name: "fullName",
                value: state.values.fullName,
                required: true,
                error: errors.fullName,
                autocomplete: "name",
              })}
              ${FormField({
                id: "email-address",
                label: "Email address",
                name: "email",
                type: "email",
                value: state.values.email,
                required: true,
                error: errors.email,
                autocomplete: "email",
                inputmode: "email",
              })}
              ${FormField({
                id: "phone-number",
                label: "Phone number",
                name: "phone",
                type: "tel",
                value: state.values.phone,
                required: false,
                hint: "Include country code if outside the United States, for example +44 20 1234 5678 or (555) 555-0123.",
                error: errors.phone,
                autocomplete: "tel",
                inputmode: "tel",
              })}
              <div class="actions">
                <button type="submit">Send message</button>
              </div>
            </form>
          </section>
        `;
      }

      function App() {
        return `
          <main id="main">
            <header class="hero">
              <span class="eyebrow">Support</span>
              <h1>Get help from our team</h1>
              <p>Use this form to reach support with a question, issue, or request. We’ll get back to you as soon as we can.</p>
            </header>
            <div class="layout">
              ${ContactForm()}
              ${SupportCopy()}
            </div>
          </main>
        `;
      }

      function validate(values) {
        const errors = {};
        if (!values.fullName.trim()) {
          errors.fullName = "Please enter your full name.";
        }
        if (!values.email.trim()) {
          errors.email = "Please enter your email address.";
        } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(values.email.trim())) {
          errors.email = "Enter a valid email address.";
        }
        return errors;
      }

      function escapeHtml(value) {
        return String(value)
          .replaceAll("&", "&amp;")
          .replaceAll("<", "&lt;")
          .replaceAll(">", "&gt;")
          .replaceAll('"', "&quot;");
      }

      function render() {
        app.innerHTML = App();
        bind();
      }

      function bind() {
        const form = document.getElementById("contact-form");
        const fields = form.querySelectorAll("input");

        fields.forEach((field) => {
          field.addEventListener("input", () => {
            state.values[field.name] = field.value;
            if (state.submitted) {
              render();
            }
          });
        });

        form.addEventListener("submit", (event) => {
          event.preventDefault();
          state.submitted = true;
          state.values = {
            fullName: form.fullName.value,
            email: form.email.value,
            phone: form.phone.value,
          };

          const errors = validate(state.values);
          if (Object.keys(errors).length) {
            render();
            const firstInvalid = form.querySelector('[aria-invalid="true"]');
            if (firstInvalid) {
              firstInvalid.focus();
            }
            return;
          }

          render();
          const status = document.querySelector(".status");
          status.textContent = "Thanks — your message is ready to send.";
          status.className = "status success";
          form.reset();
          state.submitted = false;
          state.values = { fullName: "", email: "", phone: "" };
        });
      }

      render();
    </script>
