      }

      .sidebar h2 {
        margin: 0 0 0.6rem;
        font-size: 1.25rem;
      }

      .sidebar p,
      .sidebar li {
        color: #e2e8f0;
        line-height: 1.6;
      }

      .sidebar ul {
        margin: 0.9rem 0 0;
        padding-left: 1.1rem;
      }

      .status {
        min-height: 1.5rem;
        margin: 0 0 0.25rem;
        font-weight: 600;
      }

      .status.success {
        color: #0f766e;
      }

      .status.error {
        color: var(--error);
      }

      @media (max-width: 48rem) {
